SELECT SYS_CONTEXT('USERENV','SERVER_HOST') H, SYS_CONTEXT('USERENV','SERVICE_NAME') S, SYSDATE FROM DUAL;
SELECT MNU_ID, SHT_NM, BTN_CD, API_ID FROM SCM_ADM_MNU_BTN_MPG_M WHERE MNU_ID='SCP0111' ORDER BY 2,3;
SELECT API_ID, API_URL, API_TP_CD FROM SCM_ADM_API_M WHERE API_ID LIKE 'SCP0111%' OR UPPER(API_URL) LIKE '%SCP0111%' ORDER BY 1;
SELECT PROC_NM, SORT_ORD, COL_NM, DATA_TP_CD, IN_OUT_TP_CD FROM SCM_ADM_PROC_M WHERE UPPER(PROC_NM) LIKE '%SCP0111%' ORDER BY 1,2;
SELECT OBJECT_NAME, PROCEDURE_NAME, SUBPROGRAM_ID FROM ALL_PROCEDURES WHERE OWNER='SCM_MGR' AND (OBJECT_NAME LIKE '%SCP0111%') ORDER BY 3;
SELECT OBJECT_NAME, OBJECT_TYPE, STATUS, LAST_DDL_TIME FROM ALL_OBJECTS WHERE OWNER='SCM_MGR' AND OBJECT_NAME LIKE '%SCP0111%';
